// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract MockToken {
    uint256 public lastValue;
    address public lastFrom;
    address public lastTo;

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        lastFrom = from;
        lastTo = to;
        lastValue = value;
        return true;
    }
}

contract InvMutTest is Test {
    airDrop c;
    MockToken mock;

    function setUp() public {
        c = new airDrop();
        mock = new MockToken();
    }

    function testRegression_property() public {
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);

        c.transfer(address(0xAbc), address(mock), tos, 1, 1);

        uint256 val = mock.lastValue();
        assertTrue(val == 10, "value should be 10 for correct contract");
    }
}
